const i={JPY:"¥",USD:"$",USDT:"₮"};function s(n){return i[n]||""}function o(n,t="",e=2){const u=Number(n||0).toLocaleString("en-US",{minimumFractionDigits:e,maximumFractionDigits:e});return(t?s(t):"")+u}function a(n,t=""){const e=Number(n||0),r=e>=1e3?0:e>=1?2:4;return o(e,t,r)}function m(n,t="",e=2){const r=Number(n||0),u=o(Math.abs(r),t,e);return(r>0?"+":r<0?"-":"")+u}function c(n){const t=Number(n||0);return(t>0?"+":"")+t.toFixed(2)+"%"}function f(n){const t=Number(n||0);return t>0?"up":t<0?"down":"flat"}function d(n){if(!n)return"-";const t=new Date(Number(n)*1e3),e=r=>String(r).padStart(2,"0");return`${t.getFullYear()}-${e(t.getMonth()+1)}-${e(t.getDate())} ${e(t.getHours())}:${e(t.getMinutes())}`}function g(n){const t=Number(n||0);return t>=1e8?(t/1e8).toFixed(2)+"億":t>=1e4?(t/1e4).toFixed(2)+"万":String(t)}export{d,o as m,a as p,c as r,m as s,f as t,g as v};
